# Check the full list of tools available to this agent by searching the system prompt area
# Look for tool definitions
tool_defs = await CONTEXT.search("description")
for item in tool_defs["items"]:
    print(item["offset"], item["snippet"][:200])

# Also look for any mention of a write tool
for s in ["write", "edit_file", "save", "modify"]:
    r = await CONTEXT.search(s)
    if r and len(r["items"]) > 0:
        print(f"{s}: {len(r['items'])} matches - first:", r["items"][0]["snippet"][:150])
